"""Write tests/fixtures/corpus.json: the excerpts CI's fixture index is built from.

A developer tool, run against a database holding the real parsed corpus and
at least one full `make eval` run. CI never runs it; it reads the JSON.

The excerpt keeps whole provisions (every section of an article, annex or
recital), chosen to keep the eval meaningful at a fraction of the size:

  - every provision an eval question expects;
  - for direct lookups, the same-numbered provision of every regulation, so
    "Article 12" stays a three-way collision;
  - every provision the shipped configuration ranked in a question's top
    fusion_top_k in the latest eval run: the realistic confusers;
  - the recitals the include-recitals run ranked there, so the matrix's
    recital combinations still have recitals to rank.

    uv run python -m tests.fixtures.export_corpus
"""

import json
from pathlib import Path

from regrag.config import settings
from regrag.db import Connection, connect
from regrag.evaluate import DIRECT_LOOKUP, load_questions
from regrag.models import SECTION_AWARE

OUT = Path(__file__).with_name("corpus.json")

LATEST_RUNS = """
SELECT id, metrics->'params' FROM eval_runs
WHERE run_at = (
    SELECT max(run_at) FROM eval_runs
    WHERE coalesce(metrics->>'question_set', 'questions.yaml') = 'questions.yaml'
)
"""

RETRIEVED = """
SELECT DISTINCT jsonb_array_elements_text(chunk->'citations')
FROM eval_results r, jsonb_array_elements(r.retrieved->'chunks') chunk
WHERE r.run_id = %(run_id)s AND (chunk->>'rank')::int <= %(top_k)s
"""

DOCUMENTS = "SELECT id, celex, title, source_url FROM documents WHERE celex = ANY(%(celex_ids)s)"

# Recitals are keyed by path ("recital-12"); everything else by article_no.
SECTIONS = """
SELECT s.path, s.kind, s.article_no, s.paragraph_no, s.heading, s.text
FROM sections s
WHERE s.document_id = %(document_id)s
  AND (s.article_no = ANY(%(numbers)s) OR s.path = ANY(%(recital_paths)s))
ORDER BY s.id
"""


def wanted_provisions(conn: Connection) -> set[str]:
    questions = load_questions(settings.eval_questions_path)
    wanted = {a for q in questions for a in q.expected_articles}
    for q in questions:
        if q.category == DIRECT_LOOKUP:
            for article in q.expected_articles:
                number = article.partition(":")[2]
                wanted |= {f"{celex}:{number}" for celex in settings.celex_ids}

    runs = conn.execute(LATEST_RUNS).fetchall()
    if not runs:
        raise SystemExit("no eval runs: run make eval first")
    for run_id, params in runs:
        if params["strategy"] != SECTION_AWARE or params["fts_rank_normalization"] != 0:
            continue
        retrieved = {
            row[0]
            for row in conn.execute(RETRIEVED, {"run_id": run_id, "top_k": settings.fusion_top_k})
        }
        if params["exclude_recitals"]:
            wanted |= retrieved  # the shipped configuration
        else:
            wanted |= {p for p in retrieved if ":Recital " in p}
    return wanted


def export(conn: Connection) -> dict[str, object]:
    wanted = wanted_provisions(conn)
    documents = []
    for document_id, celex, title, source_url in conn.execute(
        DOCUMENTS, {"celex_ids": settings.celex_ids}
    ).fetchall():
        numbers = [p.partition(":")[2] for p in wanted if p.startswith(f"{celex}:")]
        recital_paths = [
            "recital-" + n.removeprefix("Recital ") for n in numbers if n.startswith("Recital ")
        ]
        rows = conn.execute(
            SECTIONS,
            {"document_id": document_id, "numbers": numbers, "recital_paths": recital_paths},
        ).fetchall()
        documents.append(
            {
                "celex": celex,
                "title": title,
                "source_url": source_url,
                "sections": [
                    dict(
                        zip(
                            ("path", "kind", "article_no", "paragraph_no", "heading", "text"),
                            row,
                            strict=True,
                        )
                    )
                    for row in rows
                ],
            }
        )
    return {
        "about": (
            "Excerpts of EU regulations from EUR-Lex (reuse authorised, Commission "
            "Decision 2011/833/EU), for CI's offline eval. Generated by "
            "tests/fixtures/export_corpus.py; do not edit by hand."
        ),
        "provisions": len(wanted),
        "documents": documents,
    }


def main() -> None:
    with connect() as conn:
        corpus = export(conn)
    OUT.write_text(json.dumps(corpus, indent=1, ensure_ascii=False) + "\n")
    sections = sum(len(d["sections"]) for d in corpus["documents"])  # type: ignore[attr-defined]
    print(f"wrote {OUT}: {corpus['provisions']} provisions, {sections} sections")


if __name__ == "__main__":
    main()
